INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-sel-group', 0, 'lab', 'Список селекторов', 'Напишите один селектор, который выбирает ровно подсвеченные в задании элементы (красная рамка в предпросмотре) и больше ничего. Нужны заголовки первого и второго уровня (одним правилом, через запятую).', '', 'Запятая объединяет селекторы: h1, h2.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-sel-descendant', 1, 'lab', 'Селектор потомков', 'Напишите один селектор, который выбирает ровно подсвеченные в задании элементы (красная рамка в предпросмотре) и больше ничего. Нужны абзацы внутри блока .article, в том числе вложенные глубже.', '', 'Пробел между селекторами означает «на любой глубине внутри».', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-sel-child', 2, 'lab', 'Непосредственные дети', 'Напишите один селектор, который выбирает ровно подсвеченные в задании элементы (красная рамка в предпросмотре) и больше ничего. Нужны только пункты верхнего уровня меню .menu, вложенные пункты не нужны.', '', 'Знак > выбирает только прямых детей.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-sel-sibling', 3, 'lab', 'Соседний элемент', 'Напишите один селектор, который выбирает ровно подсвеченные в задании элементы (красная рамка в предпросмотре) и больше ничего. Нужен только абзац, который стоит сразу после заголовка h2.', '', 'Знак + выбирает ближайшего следующего соседа, знак ~ — всех следующих.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-sel-attr', 4, 'lab', 'Атрибут и начало значения', 'Напишите один селектор, который выбирает ровно подсвеченные в задании элементы (красная рамка в предпросмотре) и больше ничего. Нужны только внешние ссылки: адрес начинается с https.', '', 'Селектор атрибута: [href^="https"] — значение начинается с «https».', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-sel-ext', 5, 'lab', 'Атрибут и конец значения', 'Напишите один селектор, который выбирает ровно подсвеченные в задании элементы (красная рамка в предпросмотре) и больше ничего. Нужны только ссылки на файлы пдф: адрес заканчивается на .pdf.', '', 'Знак $ в селекторе атрибута: [href$=".pdf"] — значение заканчивается подстрокой.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-sel-nth', 6, 'lab', 'Каждый третий', 'Напишите один селектор, который выбирает ровно подсвеченные в задании элементы (красная рамка в предпросмотре) и больше ничего. Нужны пункты списка с номерами 1, 4 и 7: каждый третий, начиная с первого.', '', 'В :nth-child принимается формула: an + b, где n пробегает 0, 1, 2…', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-sel-first-last', 7, 'lab', 'Первый и последний', 'Напишите один селектор, который выбирает ровно подсвеченные в задании элементы (красная рамка в предпросмотре) и больше ничего. Нужны первый и последний пункты списка.', '', ':first-child и :last-child, объединённые запятой.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-sel-not', 8, 'lab', 'Всё, кроме', 'Напишите один селектор, который выбирает ровно подсвеченные в задании элементы (красная рамка в предпросмотре) и больше ничего. Нужны кнопки .btn, которые не отключены (у отключённых есть класс disabled).', '', 'Псевдокласс :not(...) исключает совпавшее.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-sel-is', 9, 'lab', 'Короткая запись списка', 'Напишите один селектор, который выбирает ровно подсвеченные в задании элементы (красная рамка в предпросмотре) и больше ничего. Нужны заголовки h2 и абзацы внутри блока .article, но не списки и не то, что снаружи. Общую часть .article можно записать один раз.', '', ':is(h2, p) подставляет список на место одного селектора: .article :is(…).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-sel-has', 10, 'lab', 'Родитель по содержимому', 'Напишите один селектор, который выбирает ровно подсвеченные в задании элементы (красная рамка в предпросмотре) и больше ничего. Нужны только карточки .card, в которых есть картинка.', '', 'Псевдокласс :has(...) выбирает элемент по тому, что лежит внутри него.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-sel-low-spec', 11, 'lab', 'Селектор с низкой специфичностью', 'Напишите один селектор, который выбирает ровно подсвеченные в задании элементы (красная рамка в предпросмотре) и больше ничего. Нужны все элементы с классом note, но специфичность селектора не должна превышать (0, 1, 0), и идентификаторы запрещены.', '', 'Один класс даёт (0, 1, 0). Всё, что длиннее, уже тяжелее.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-css-hover', 12, 'lab', 'Стиль при наведении', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. У кнопки .btn обычный фон #2563eb уже задан. Сделайте так, чтобы при наведении курсора фон становился #1d4ed8, а в обычном состоянии оставался прежним.', '', 'Правило с псевдоклассом :hover применяется, пока курсор над элементом: .btn:hover { … }.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-css-focus', 13, 'lab', 'Видимый фокус клавиатуры', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. У поля ввода есть тонкая серая рамка. Не убирая её, добавьте для фокуса с клавиатуры (:focus-visible) сплошной контур (outline) цвета #f59e0b толщиной не менее 2px.', '', 'input:focus-visible { outline: 2px solid …; } — контур рисуется вне рамки и не сдвигает вёрстку.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-css-checked', 14, 'lab', 'Отмеченный чекбокс', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Подпись при чекбоксе должна становиться зелёной (#15803d), когда он отмечен; у неотмеченного подпись остаётся цвета #444. Используйте :checked и соседний комбинатор.', '', 'input:checked + label { … } — подпись стоит сразу после чекбокса.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-css-invalid', 15, 'lab', 'Подсветка неверного поля', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. У поля электронной почты рамка серая (#94a3b8). Когда значение не проходит проверку (состояние :invalid), рамка должна стать красной (#dc2626); в обычном состоянии рамка остаётся серой. Вручную классов не ставьте: пользуйтесь псевдоклассом.', '', 'Псевдокласс :invalid подходит полю, значение которого не проходит проверку, например type="email" с текстом без собаки.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-css-after', 16, 'lab', 'Стрелка через ::after', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. После текста ссылки .ext должна появляться стрелка «→», добавленная из CSS, синего цвета #2563eb и с отступом слева не менее 4px. Сам текст в разметке менять нельзя.', '', 'Псевдоэлемент a::after со свойством content: "→". Без content он не появится.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-css-order', 17, 'lab', 'Победить порядком', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Элементу с классами a b подходят два правила одинаковой специфичности: .a { color: red } и .b { color: green }, побеждает последнее. Сделайте текст красным, не усиливая селектор и не трогая !important.', '', 'При равной специфичности выигрывает правило, которое записано ниже. Ваш CSS идёт после того, что уже есть.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-css-specificity', 18, 'lab', 'Победить по специфичности', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. В документе уже есть правило #card .text { color: red }. Сделайте текст синим без !important: ваше правило должно оказаться специфичнее.', '', 'Селектор #card .text весит (1, 1, 0). Добавьте ещё один класс или тип, не трогая ничего другого.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 16, 'w16-css-no-important', 19, 'lab', 'Без !important и без id', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. В документе уже есть правило .list .item.active { color: gray }. Сделайте активный пункт красным, не прибегая ни к !important, ни к идентификаторам: спор решает порядок правил.', '', 'Повторите тот же вес — три класса — и запишите правило ниже: при равной специфичности побеждает последнее.', '{}');
